mapper.select:
SELECT usp.id, usp.user_mis, usp.user_org, usp.stage_id, usp.verify_status, usp.submitted_value, usp.passed_at, usp.lane, usp.url, usp.reviewed_at, usp.reviewed_by, usp.reject_reason, usp.deleted_flag, usp.add_time, usp.create_time, usp.update_time FROM user_stage_progress usp JOIN stage s ON s.id = usp.stage_id AND s.deleted_flag = 0 WHERE s.verify_type = 'manual' AND usp.deleted_flag = 0
AND usp.verify_status = #{status}
ORDER BY usp.create_time DESC LIMIT #{offset}, #{pageSize}
